import { useFormStatus } from "react";  // Import the useFormStatus hook from React.

function MyFormComponent() {
  // Destructure the properties from useFormStatus hook.
  // - `pending`: Tracks if the form is in the process of being submitted.
  // - `error`: Contains any error that occurred during submission.
  // - `success`: Indicates if the form was submitted successfully.
  const { pending, error, success } = useFormStatus();

  return (
    <form>
      {/* If form is pending submission, display a message */}
      {pending && <p>Submitting....</p>}

      {/* If an error occurred during submission, display the error message */}
      {error && <p>Error: {error.message}</p>}

      {/* If form submission is successful, display success message */}
      {success && <p>Form submitted successfully!</p>}
    </form>
  );
}

import { useActionState } from "react";  // Import the useActionState hook from React.

function MyActionComponent() {
  // Destructure the properties from useActionState hook.
  // - `pending`: Indicates if the action is currently in progress.
  // - `error`: Contains any error that occurred during the action.
  // - `success`: Indicates if the action was completed successfully.
  // We pass a unique name (e.g., "myActionName") to track the specific action.
  const { pending, error, success } = useActionState("myActionName");

  return (
    <div>
      {/* If the action is in progress, display a "pending" message */}
      {pending && <p>Action in progress</p>}

      {/* If an error occurred during the action, display the error message */}
      {error && <p>Error: {error.message}</p>}

      {/* If the action was completed successfully, display a success message */}
      {success && <p>Action completed successfully</p>}
    </div>
  );
}

import { useOptimistic } from "react";  // Import the useOptimistic hook from React.

function MyOptimisticComponent() {
  // useOptimistic hook is used to optimistically update the state while the action is in progress.
  // - The first argument is the initial state ({ count: 0 }).
  // - The second argument is a function that describes how to update the state.
  //   It takes two arguments: `currentState` (the previous state) and `newUpdate` (the change to apply).
  const [optimisticState, setOptimisticState] = useOptimistic(
    { count: 0 },  // Initial state: the count starts at 0
    (currentState, newUpdate) => ({ count: currentState.count + newUpdate })  // State update function: increments count
  );

  return (
    <div>
      {/* Display the current count */}
      <p>Count: {optimisticState.count}</p>

      {/* When the button is clicked, optimistically update the state by incrementing the count */}
      <button onClick={() => setOptimisticState(1)}>Increment</button>
    </div>
  );
}

